import { readFileSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { NodeKernelHost } from '../host/src/node-kernel-host.ts';
import { KandeloImageFs } from '../images/vfs/lib/kandelo-image-fs.ts';
const base = new URL('../local-binaries/source-only-v1/', import.meta.url);
const fs = KandeloImageFs.create();
fs.setImageCapacity(256 * 1024 * 1024);
fs.mkdir('/bin', 0o755); fs.mkdir('/home', 0o755); fs.mkdir('/home/maker', 0o755, 1000, 1000);
for (const name of ['bash', 'coreutils']) fs.writeFile('/bin/' + name, readFileSync(new URL('programs/wasm32/' + name + '.wasm', base)), 0o755);
for (const name of ['dd','sync','stat']) fs.symlink('/bin/coreutils', '/bin/' + name);
const image = await fs.saveImage();
writeFileSync(new URL('./write-throughput.vfs', import.meta.url), image);
const wasm = new Uint8Array(readFileSync(new URL('kernel.wasm', base)));
const rows = [];
const allowPressureEnospc = process.argv.includes('--allow-pressure-enospc');
for (const MiB of [16, 128]) for (let round = 0; round < 3; round++) {
 const dir = mkdtempSync(join(tmpdir(), 'persistent-write-bench-'));
 let output=''; let closed=false; const diagnostics: string[]=[];
 const host = new NodeKernelHost({onHostDiagnostic: diagnostic=>{diagnostics.push(diagnostic.message)},rootfsImage:image, experimentalResizablePersistencePath: join(dir,'journal'), onStdout:(_pid,bytes)=>{output+=new TextDecoder().decode(bytes)},onStderr:(_pid,bytes)=>{output+=new TextDecoder().decode(bytes)}});
 try {
  await host.init(wasm.slice().buffer);
  const start=performance.now();
  const {exit}=await host.spawnFromVfs('/bin/bash',['bash','-ec',`dd if=/dev/zero of=/home/maker/write bs=65536 count=${MiB * 16}; sync; test "$(stat -c %s /home/maker/write)" = ${MiB * 1024 * 1024}`],{uid:1000,gid:1000,env:['PATH=/bin','HOME=/home/maker']});
  const code=await exit; const ms=performance.now()-start;
  if(code!==0 && !(allowPressureEnospc && MiB===128 && output.includes('No space left on device'))) throw new Error(output);
  rows.push({round:round+1,MiB,ms,exitCode:code,MiBps:code===0 ? MiB*1000/ms : null,...(code!==0 ? {error:output} : {})});
 } finally {await host.destroy();if(host.getPersistenceShutdownFailure()!==null || diagnostics.some(message=>message.includes('realm termination failed')))throw new Error('Benchmark shutdown unconfirmed; retained '+dir+' '+diagnostics.join('; '));closed=true;if(closed)rmSync(dir,{recursive:true,force:true});}
}
let timerResolutionMs=Infinity; for(let i=0,previous=performance.now();i<10000;i++){const now=performance.now();if(now>previous)timerResolutionMs=Math.min(timerResolutionMs,now-previous);previous=now;}
const evidence={timerResolutionMs,imageSha256:createHash('sha256').update(image).digest('hex'),node:process.version,kernel: createHash('sha256').update(wasm).digest('hex'),rows,scope:'Three fresh machines for each of 16 and 128 MiB in one Node parent; sequential persistent write plus sync; guest shell/process startup included, boot excluded.'};
writeFileSync(new URL('./write-throughput-node.json',import.meta.url),JSON.stringify(evidence,null,2));
console.log(JSON.stringify(evidence));

