import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { expect } from '../playwright-test';
import { opfsTest as test } from './support/opfs-page';
const root = resolve(import.meta.dirname, '../../..');
test('measure sixteen and 128 MiB persistent writes plus sync', async ({ page, baseURL, browserName }, info) => {
 test.setTimeout(180_000);
 const kernelUrl = new URL('/write-throughput-kernel.wasm', baseURL).href;
 const imageUrl = new URL('/write-throughput.vfs', baseURL).href;
 await page.route(kernelUrl, route => route.fulfill({body: readFileSync(resolve(root,'local-binaries/source-only-v1/kernel.wasm'))}));
 await page.route(imageUrl, route => route.fulfill({body: readFileSync(resolve(root,'.context/write-throughput.vfs'))}));
 await page.goto(new URL('/trap-signal-test.html',baseURL).href);
 const result = await page.evaluate(async ({moduleUrl,kernelUrl,imageUrl,allowPressureEnospc}) => {
  const {BrowserKernel} = await import(moduleUrl);
  const kernelWasm=await (await fetch(kernelUrl)).arrayBuffer();
  const image=new Uint8Array(await (await fetch(imageUrl)).arrayBuffer());
  let timerResolutionMs=Infinity; for(let i=0,previous=performance.now();i<10000;i++){const now=performance.now();if(now>previous)timerResolutionMs=Math.min(timerResolutionMs,now-previous);previous=now;}
  const rows=[];
  for(const MiB of [16,128]) for(let round=0;round<3;round++) {
   const name='write-throughput-'+crypto.randomUUID();
   let output='';
   const kernel=new BrowserKernel({kernelOwnedFs:true,onStdout:(bytes:Uint8Array)=>{output+=new TextDecoder().decode(bytes)},onStderr:(bytes:Uint8Array)=>{output+=new TextDecoder().decode(bytes)}});
   let closed=false;
   try {
    await kernel.initFromImage({kernelWasm:kernelWasm.slice(0),vfsImage:image,experimentalResizablePersistenceName:name,persistentComputerName:name});
    const start=performance.now();
    const {exit}=await kernel.spawnFromVfs('/bin/bash',['bash','-ec',`dd if=/dev/zero of=/home/maker/write bs=65536 count=${MiB*16}; sync; test "$(stat -c %s /home/maker/write)" = ${MiB*1024*1024}`],{uid:1000,gid:1000,env:['PATH=/bin','HOME=/home/maker']});
    const code=await exit;const ms=performance.now()-start;
    if(code!==0 && !(allowPressureEnospc && MiB===128 && output.includes('No space left on device')))throw new Error(output);
    rows.push({round:round+1,MiB,ms,exitCode:code,MiBps:code===0?MiB*1000/ms:null,...(code!==0?{error:output}:{})});
   } finally {
    await kernel.destroy();closed=!kernel.hasUnconfirmedKernelQuiescence();
    if(!closed)throw new Error('Benchmark kernel quiescence unconfirmed; retained '+name);
    if(closed) {
     const storage=await navigator.storage.getDirectory();
     const overlays=await storage.getDirectoryHandle('kandelo-persistent-overlay');
     for await(const key of overlays.keys())if(key.startsWith(name+'.'))await overlays.removeEntry(key,{recursive:true});
    }
   }
  }
  return {timerResolutionMs,rows,userAgent:navigator.userAgent,scope:'Three fresh machines for each of 16 and 128 MiB in one browser parent; persistent write plus sync; guest shell/process startup included, boot excluded.'};
 },{moduleUrl:new URL('/@fs/'+resolve(root,'host/src/browser-kernel-host.ts'),baseURL).href,kernelUrl,imageUrl,allowPressureEnospc:process.env.KANDELO_WRITE_BENCH_ALLOW_ENOSPC==='1'});
 expect(result.rows).toHaveLength(6);
 writeFileSync(resolve(root,'.context/write-throughput-browser.json'),JSON.stringify({browserName,...result},null,2));
 await info.attach('persistent-write-throughput',{contentType:'application/json',body:JSON.stringify(result)});
 console.log('PERSISTENT_WRITE_BENCHMARK '+JSON.stringify(result));
});
